use super::*;
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
#[test]
fn actual_sequence_storage_admission_keeps_backing_on_caller_before_return_and_reports_null_work(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let count=row["count"].as_u64().unwrap()as usize;let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);let mut output=None;let d=<Vec<u64>as NativeSequenceCollection<u64>>::storage_demand(count).unwrap();assert_eq!(d.copy_bytes,0);
 for g in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut control,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(output.is_none());}
 let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut control,RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);fuel-=turn.work;assert!(turn.result.is_err());assert!(output.is_none());assert_eq!(control.owned_bytes(),0);
 let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut control,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,turn.work);let pointer=output.as_ref().unwrap().as_ptr();let capacity=output.as_ref().unwrap().capacity();assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),row["empty"]);let(cached,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||<Vec<u64>as NativeSequenceCollection<u64>>::admit_storage(&mut output,count,&mut control,Default::default()));assert_eq!(cached.work,0);let error=cached.result.unwrap_err();assert_eq!(error.primary.as_ref().unwrap().kind,ValueRefusalKind::InvariantViolated);assert_eq!(error.retained_progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.as_ref().unwrap().capacity(),capacity);
 let mut owner=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).map_err(|(e,_)|e).unwrap();for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,owner.last_turn_work());}assert!(owner.terminal_is_empty());
}
